        .settings-action-button.reset:hover { background: linear-gradient(to bottom, var(--theme-cancel-hover), #78909c); box-shadow: var(--shadow-medium); transform: translateY(-1px); }
        .setting-separator { height: 1px; background-color: var(--theme-border-light); margin: 25px 0; }
        .preset-section-title label { font-weight: bold; color: var(--theme-text-light); flex-basis: auto !important; text-align: left; margin-bottom: 5px; }
        .preset-section-title span { display: none; }
