        .preset-scheme-button { background-color: var(--theme-bg-medium); border: 1px solid var(--theme-border-light); border-radius: var(--border-radius-small); padding: 8px; cursor: pointer; transition: all 0.2s ease; display: flex; flex-direction: column; align-items: center; text-align: center; box-shadow: var(--shadow-subtle); }
        .preset-scheme-button:hover { border-color: var(--theme-accent-orange-light); transform: translateY(-2px); box-shadow: var(--shadow-medium); }
        .preset-swatch { width: 40px; height: 40px; border-radius: 50%; margin-bottom: 8px; display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden; border: 3px solid; box-shadow: inset 0 0 3px rgba(0,0,0,0.2); }
        .preset-swatch-inner { width: 50%; height: 50%; border-radius: 50%; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); box-shadow: 0 0 2px rgba(0,0,0,0.3); }
        .preset-swatch-text { position: absolute; bottom: 2px; right: 4px; font-size: 10px; font-weight: bold; opacity: 0.8; text-shadow: 1px 1px 1px rgba(0,0,0,0.4); }
