        function applySettings(settings, mapInterfaceElement) {
            document.documentElement.style.setProperty('--font-main', settings.fontFamily);
            document.documentElement.style.setProperty('--font-title', settings.titleFontFamily);
            document.documentElement.style.setProperty('--theme-text-light', settings.fontColor);
            document.documentElement.style.setProperty('--theme-accent-orange', settings.uiColor);
            document.documentElement.style.setProperty('--theme-button-color', settings.buttonColor);
            document.documentElement.style.setProperty('--theme-bg-dark', settings.uiBgColor);
            document.documentElement.style.setProperty('--font-size-base', settings.fontSize);

            // Calculate derived colors
            try {
                const calculateColor = (hex, amount) => {
                    let r = parseInt(hex.slice(1, 3), 16);
                    let g = parseInt(hex.slice(3, 5), 16);
                    let b = parseInt(hex.slice(5, 7), 16);
                    r = Math.min(255, r + amount); g = Math.min(255, g + amount); b = Math.min(255, b + amount);
                    return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
                };
                document.documentElement.style.setProperty('--theme-accent-orange-light', calculateColor(settings.uiColor, 30));
                document.documentElement.style.setProperty('--theme-button-hover-color', calculateColor(settings.buttonColor, 20));
                document.documentElement.style.setProperty('--theme-bg-medium', calculateColor(settings.uiBgColor, 18));
                document.documentElement.style.setProperty('--theme-bg-light', calculateColor(settings.uiBgColor, 36));
                document.documentElement.style.setProperty('--theme-border-light', calculateColor(settings.uiBgColor, 50));
            } catch (e) {
                console.error("Error calculating derived UI colors:", e);
                // Apply fallbacks if calculation fails
                document.documentElement.style.setProperty('--theme-accent-orange-light', settings.uiColor);
                document.documentElement.style.setProperty('--theme-button-hover-color', settings.buttonColor);
                document.documentElement.style.setProperty('--theme-bg-medium', '#3e4451');
                document.documentElement.style.setProperty('--theme-bg-light', '#505663');
                document.documentElement.style.setProperty('--theme-border-light', '#606673');
            }

            document.body.classList.toggle('no-shadows', !settings.shadowsEnabled);

            const quickCommandsSection = document.getElementById('game-actions-section');
            if (quickCommandsSection) {
                quickCommandsSection.classList.toggle('hidden-by-settings', !settings.showQuickCommands);
                 console.log("Quick command visibility set. show:", settings.showQuickCommands, "Classes:", quickCommandsSection.className);
            }

            // Toggle Bullet Chat visibility
            const bulletChatContainer = document.getElementById('bullet-chat-container');
            if (bulletChatContainer) {
                bulletChatContainer.classList.toggle('hidden-by-settings', !settings.showBulletChat);
                console.log("Bullet chat visibility set. show:", settings.showBulletChat, "Classes:", bulletChatContainer.className);
            }
        }

        function saveSettings(settings) {
            try { localStorage.setItem('mapPluginSettings', JSON.stringify(settings)); }
            catch (e) { console.error("Failed to save settings to localStorage:", e); }
        }

        function loadSettings() {
            try {
                const saved = localStorage.getItem('mapPluginSettings');
                if (saved) return { ...defaultSettings, ...JSON.parse(saved) };
            } catch (e) { console.error("Failed to load settings from localStorage:", e); }
            return { ...defaultSettings };
        }

        function updateSettingsUI(settings, elements) {
             if (!elements) { console.error("Elements object not provided to updateSettingsUI"); return; }
