        // --- Draggable Element Logic ---
        function makeDraggable(element, handle) {
            let pos1 = 0, pos2 = 0, pos3 = 0, pos4 = 0;
            let isDragging = false;

            const dragMouseDown = (e) => {
                e = e || window.event;
                // Allow dragging only with left mouse button or touch
                if (e.type === 'mousedown' && e.button !== 0) return;
                e.preventDefault(); // Prevent text selection during drag

                pos3 = e.clientX || e.touches[0].clientX;
                pos4 = e.clientY || e.touches[0].clientY;
                isDragging = true;
                element.classList.add('dragging'); // Add class for visual feedback

                document.onmouseup = closeDragElement;
                document.ontouchend = closeDragElement;
                document.onmousemove = elementDrag;
                document.ontouchmove = elementDrag;
            };

            const elementDrag = (e) => {
                if (!isDragging) return;
                e = e || window.event;
                e.preventDefault();

                const currentX = e.clientX || e.touches[0].clientX;
                const currentY = e.clientY || e.touches[0].clientY;

                pos1 = pos3 - currentX;
                pos2 = pos4 - currentY;
                pos3 = currentX;
                pos4 = currentY;

                // Calculate new position, constrained within viewport
                const parentRect = element.parentElement.getBoundingClientRect(); // Use map-interface as boundary
                const elementRect = element.getBoundingClientRect();

                let newTop = element.offsetTop - pos2;
                let newLeft = element.offsetLeft - pos1;

                // Constrain top/bottom
                newTop = Math.max(0, newTop); // Don't go above parent top
                newTop = Math.min(parentRect.height - elementRect.height, newTop); // Don't go below parent bottom

                // Constrain left/right
                newLeft = Math.max(0, newLeft); // Don't go left of parent left
                newLeft = Math.min(parentRect.width - elementRect.width, newLeft); // Don't go right of parent right


                element.style.top = newTop + "px";
                element.style.left = newLeft + "px";
            };

            const closeDragElement = () => {
                isDragging = false;
                element.classList.remove('dragging'); // Remove dragging class
                document.onmouseup = null;
                document.ontouchend = null;
                document.onmousemove = null;
                document.ontouchmove = null;
            };

            if (handle) {
                handle.onmousedown = dragMouseDown;
                handle.ontouchstart = dragMouseDown;
            } else {
                element.onmousedown = dragMouseDown;
                element.ontouchstart = dragMouseDown;
            }
        }
        // --- End Draggable Element Logic ---


        function init() {
            setupEventListeners();
            // Delay setupSettingsPanel slightly
            setTimeout(() => {
                try { setupSettingsPanel(); }
                catch (e) { console.error("Error during delayed setupSettingsPanel execution:", e); }
