            if (loadSettings().showBulletChat) {
                if (mapData && mapData.bullets && mapData.bullets.length > 0) {
                    console.log("Displaying parsed bullets from map data (init).");
                    displayParsedBullets(mapData.bullets); // Display parsed bullets
                } else {
                    console.log("No parsed bullets found, displaying placeholder bullets (init).");
                    setTimeout(generateAndDisplayPlaceholderBullets, 1500); // Display placeholders after a delay
                }
            } else {
                 console.log("Bullet chat disabled in settings, not displaying bullets.");
            }
        }

        document.addEventListener('DOMContentLoaded', init);
