        .setting-item input[type="color"]::-webkit-color-swatch { border: none; border-radius: calc(var(--border-radius-small) - 1px); }
        .setting-item input[type="color"]:hover { border-color: var(--theme-accent-orange-light); box-shadow: var(--shadow-medium); }
        .setting-item input[type="checkbox"] { width: 18px; height: 18px; cursor: pointer; accent-color: var(--theme-accent-orange); margin-left: 5px; flex-grow: 0; }
